const { withXcodeProject } = require('@expo/config-plugins');

/**
 * Pins automatic code signing into the generated Xcode project.
 *
 * `ios/` is regenerated by `expo prebuild` and gitignored, so a team selected
 * in the Xcode UI is lost on the next prebuild and the build fails with "no
 * signing certificate found". This reapplies it every time.
 *
 * The certificate and provisioning profile live in the keychain and in
 * ~/Library/Developer/Xcode/UserData/Provisioning Profiles/, both outside the
 * repo — this plugin only restores the pointer to them.
 *
 * Team id resolution, first match wins:
 *   1. APPLE_TEAM_ID in the environment (CI, or an adopter of this kit)
 *   2. the `teamId` prop in app.json
 * With neither, the plugin is a no-op and Xcode falls back to manual selection.
 *
 * @type {import('@expo/config-plugins').ConfigPlugin<{ teamId?: string }>}
 */
const withIosSigning = (config, props = {}) => {
  const teamId = process.env.APPLE_TEAM_ID || props.teamId;
  if (!teamId) return config;

  return withXcodeProject(config, (modConfig) => {
    const project = modConfig.modResults;
    const configurations = project.pbxXCBuildConfigurationSection();

    for (const entry of Object.values(configurations)) {
      // The section is interleaved with `<uuid>_comment` string entries.
      if (!entry || typeof entry !== 'object' || !entry.buildSettings) continue;

      // Project-level configurations carry no bundle identifier; only the app
      // target's do. Signing belongs on the target, not the project.
      const settings = entry.buildSettings;
      if (settings.PRODUCT_BUNDLE_IDENTIFIER === undefined) continue;

      settings.DEVELOPMENT_TEAM = teamId;
      settings.CODE_SIGN_STYLE = 'Automatic';
    }

    // Mirror it into TargetAttributes so Xcode's Signing & Capabilities pane
    // shows the team as selected rather than blank.
    const attributes =
      project.getFirstProject()?.firstProject?.attributes?.TargetAttributes;
    if (attributes) {
      for (const target of Object.values(attributes)) {
        if (target && typeof target === 'object') target.DevelopmentTeam = teamId;
      }
    }

    return modConfig;
  });
};

module.exports = withIosSigning;
